// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(actor != newOwner);
        // current owner is address(0); use it (via prank) to hand ownership to the fuzzed actor
        vm.prank(address(0));
        c.transferOwnership(actor);
        vm.prank(actor);
        c.transferOwnership(newOwner);
        // Rule: for any (actor, newOwner), after transferOwnership the owner equals newOwner.
        assertTrue(c.owner() == newOwner);
    }
}
